// --- Tracking Utility ---
const trackEvent = (eventName: string, params: object = {}) => {
  console.log(`[GA4 Event]: ${eventName}`, params);
  // @ts-ignore
  if (window.gtag) {
    // @ts-ignore
    window.gtag('event', eventName, params);
  }
};

