);

const Navbar = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <nav className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${scrolled ? 'bg-slate-950/80 backdrop-blur-lg border-b border-white/10 py-3' : 'bg-transparent py-6'}`}>
      <div className="container mx-auto px-6 flex justify-between items-center">
        <div className="flex items-center gap-2">
          <div className="w-10 h-10 rounded-lg bg-gradient-to-br from-purple-600 to-cyan-400 flex items-center justify-center shadow-lg shadow-purple-500/20">
            <Zap className="text-white fill-white" size={24} />
          </div>
          <span className="text-2xl font-bold tracking-tight text-white font-display">AuraFlow<span className="text-purple-400">Systems</span></span>
        </div>

        <div className="hidden md:flex items-center gap-8">
          {['Hizmetler', 'Süreç', 'Sonuçlar', 'Fiyatlandırma'].map((item) => (
            <a key={item} href={`#${item.toLowerCase()}`} className="text-slate-300 hover:text-white transition-colors text-sm font-medium">
              {item}
            </a>
          ))}
          <button 
            onClick={() => {
              trackEvent('click_book_call', { location: 'navbar' });
              document.getElementById('booking')?.scrollIntoView({ behavior: 'smooth' });
            }}
            className="px-5 py-2.5 rounded-full bg-white text-slate-950 text-sm font-bold hover:bg-purple-400 hover:text-white transition-all shadow-lg"
