const CookieConsent = () => {
  const [show, setShow] = useState(false);

  useEffect(() => {
    const consent = localStorage.getItem('cookie-consent');
    if (!consent) setShow(true);
  }, []);

  if (!show) return null;

  return (
    <motion.div 
      initial={{ y: 100 }}
      animate={{ y: 0 }}
      className="fixed bottom-6 left-6 right-6 md:left-auto md:right-6 md:w-96 z-[100] p-6 bg-slate-900 border border-white/10 rounded-2xl shadow-2xl backdrop-blur-xl"
    >
      <h6 className="text-white font-bold mb-2">Çerez Politikası</h6>
      <p className="text-xs text-slate-400 mb-4 leading-relaxed">
        Size daha iyi bir hizmet sunabilmek için çerezleri kullanıyoruz. Sitemizi kullanarak bunu kabul etmiş olursunuz.
      </p>
      <div className="flex gap-2">
        <button 
          onClick={() => {
            localStorage.setItem('cookie-consent', 'true');
            setShow(false);
          }}
          className="flex-1 py-2 bg-white text-slate-950 text-xs font-bold rounded-lg hover:bg-purple-400 hover:text-white transition-all"
        >
          Kabul Et
        </button>
        <button onClick={() => setShow(false)} className="px-4 py-2 text-xs text-slate-500">Reddet</button>
      </div>
    </motion.div>
  );
};

