const BackToTop = () => {
  const [show, setShow] = useState(false);
  useEffect(() => {
    const handle = () => setShow(window.scrollY > 500);
    window.addEventListener('scroll', handle);
    return () => window.removeEventListener('scroll', handle);
  }, []);

  return (
    <AnimatePresence>
      {show && (
        <motion.button 
          initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
          onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
          className="fixed bottom-24 right-6 w-10 h-10 bg-white/10 backdrop-blur-md border border-white/20 rounded-full flex items-center justify-center text-white z-40 hover:bg-white/20"
        >
          <ArrowUpRight size={20} className="-rotate-45" />
        </motion.button>
      )}
    </AnimatePresence>
  );
};

const CustomCursor = () => {
  const [pos, setPos] = useState({ x: 0, y: 0 });

  useEffect(() => {
    const handle = (e: MouseEvent) => setPos({ x: e.clientX, y: e.clientY });
    window.addEventListener('mousemove', handle);
    return () => window.removeEventListener('mousemove', handle);
  }, []);

  return (
    <div 
      className="fixed pointer-events-none z-[9999] w-[400px] h-[400px] bg-purple-600/10 blur-[100px] rounded-full mix-blend-screen hidden md:block"
      style={{ left: pos.x - 200, top: pos.y - 200 }}
    />
  );
};

