const App = () => {
  const [lang, setLang] = useState<LangCode>('ar');
  const [formStep, setFormStep] = useState<'form' | 'success' | 'error'>('form');
  const [scrolled, setScrolled] = useState(false);
  const t = translations[lang];
  const calendlyRef = useRef<HTMLDivElement>(null);
  const formRef = useRef<HTMLElement>(null);

  useEffect(() => {
    document.documentElement.dir = t.dir;
    const handleScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, [lang]);

  const scrollToCalendly = () => {
    calendlyRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const scrollToForm = () => {
    formRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleLeadSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const data = Object.fromEntries(formData.entries());

    try {
      await fetch('https://script.google.com/macros/s/AKfycbxZCMBpwBq3Ci5tvyiRbenoBLreftXWiKI2oZBRLIBL7vii10yM_DjBwFtEA_LMyZnKDg/exec', {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(data)
      });
      setFormStep('success');
      setTimeout(scrollToCalendly, 1500);
    } catch (error) {
      setFormStep('error');
      setTimeout(scrollToCalendly, 1000);
    }
  };

  return (
    <div className="bg-slate-950 text-slate-200 selection:bg-indigo-500/30 font-sans">
