    if (!heroImage) generateHeroImage();
    return () => window.removeEventListener('scroll', handleScroll);
  }, [lang]);

  const generateHeroImage = async () => {
    setIsGenerating(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = "A premium, futuristic AI neural brain core in DEEP RED and DARK BLACK aesthetic. Glowing red energy trails, connected to floating minimal glass UI panels. High contrast, technical, SaaS aesthetic, 4K, professional, clean minimal style. Dark environment with dramatic red lighting.";
