    );
  }

  return (
    <div className="bg-white/[0.03] backdrop-blur-2xl border border-white/10 rounded-[32px] p-8 md:p-12 shadow-2xl relative overflow-hidden">
      <div className="absolute top-0 right-0 w-32 h-32 bg-red-600/10 blur-[60px] rounded-full" />
      <h3 className="text-2xl md:text-3xl font-black text-white mb-8 text-center">{t.formTitle}</h3>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div>
          <label className="block text-xs font-black uppercase tracking-widest text-slate-500 mb-2">{t.formLabelName}</label>
          <input 
            required
            type="text"
            value={formData.name}
            onChange={e => setFormData({ ...formData, name: e.target.value })}
            className="w-full bg-black/40 border border-white/10 rounded-2xl px-6 py-4 text-white focus:outline-none focus:border-red-500/50 transition-all"
            placeholder="..."
          />
        </div>

        <div>
          <label className="block text-xs font-black uppercase tracking-widest text-slate-500 mb-2">{t.formLabelEmail}</label>
          <input 
            required
            type="email"
            value={formData.email}
            onChange={e => setFormData({ ...formData, email: e.target.value })}
            className="w-full bg-black/40 border border-white/10 rounded-2xl px-6 py-4 text-white focus:outline-none focus:border-red-500/50 transition-all"
            placeholder="..."
