const LeadForm = ({ lang, t }: { lang: LangCode, t: any }) => {
  const [formData, setFormData] = useState({ name: '', email: '', source: '' });
  const [status, setStatus] = useState<'idle' | 'submitting' | 'success' | 'error'>('idle');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setStatus('submitting');
    try {
      const payload = {
        name: formData.name,
        email: formData.email,
        source: formData.source,
        timestamp: new Date().toISOString()
      };
      // Webhook call logic remains ready for integration
      await fetch(WEBHOOK_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      setStatus('success');
      setFormData({ name: '', email: '', source: '' });
    } catch (err) {
      console.error(err);
      setStatus('error');
    }
  };

  if (status === 'success') {
    return (
      <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="text-center p-12 bg-red-950/20 border border-red-500/20 rounded-3xl backdrop-blur-xl">
        <CheckCircle2 size={64} className="text-red-500 mx-auto mb-6" />
        <h3 className="text-2xl font-bold text-white mb-2">{t.formSuccess}</h3>
      </motion.div>
    );
  }

  return (
    <div className="bg-white/[0.03] backdrop-blur-2xl border border-white/10 rounded-[32px] p-8 md:p-12 shadow-2xl relative overflow-hidden">
      <div className="absolute top-0 right-0 w-32 h-32 bg-red-600/10 blur-[60px] rounded-full" />
      <h3 className="text-2xl md:text-3xl font-black text-white mb-8 text-center">{t.formTitle}</h3>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div>
          <label className="block text-xs font-black uppercase tracking-widest text-slate-500 mb-2">{t.formLabelName}</label>
          <input 
            required
            type="text"
            value={formData.name}
            onChange={e => setFormData({ ...formData, name: e.target.value })}
            className="w-full bg-black/40 border border-white/10 rounded-2xl px-6 py-4 text-white placeholder:text-slate-700 focus:outline-none focus:border-red-500/50 transition-all"
            placeholder={lang === 'ar' ? "أحمد خالد" : "Ahmed Khaled"}
          />
        </div>

        <div>
          <label className="block text-xs font-black uppercase tracking-widest text-slate-500 mb-2">{t.formLabelEmail}</label>
          <input 
            required
            type="email"
            autoComplete="email"
            value={formData.email}
            onChange={e => setFormData({ ...formData, email: e.target.value })}
            className="w-full bg-black/40 border border-white/10 rounded-2xl px-6 py-4 text-white placeholder:text-slate-700 focus:outline-none focus:border-red-500/50 transition-all"
            placeholder="example@email.com"
          />
        </div>

        <div>
          <label className="block text-xs font-black uppercase tracking-widest text-slate-500 mb-2">{t.formLabelSource}</label>
          <select 
            required
            value={formData.source}
            onChange={e => setFormData({ ...formData, source: e.target.value })}
            className="w-full bg-black/40 border border-white/10 rounded-2xl px-6 py-4 text-white focus:outline-none focus:border-red-500/50 appearance-none transition-all"
          >
            <option value="" disabled className="bg-slate-900">Select an option</option>
            <option value="Instagram" className="bg-slate-900">Instagram</option>
            <option value="Facebook" className="bg-slate-900">Facebook</option>
            <option value="WhatsApp" className="bg-slate-900">WhatsApp</option>
            <option value="YouTube" className="bg-slate-900">YouTube</option>
            <option value="Other" className="bg-slate-900">Other</option>
          </select>
        </div>

        <button 
          disabled={status === 'submitting'}
          className="w-full bg-red-600 hover:bg-red-700 disabled:bg-red-800 text-white font-black py-5 rounded-2xl shadow-xl shadow-red-600/20 transition-all flex items-center justify-center gap-3 group active:scale-95"
        >
          {status === 'submitting' ? <RefreshCw className="animate-spin" size={20} /> : <Zap size={20} className="group-hover:animate-pulse" />}
          {t.formSubmit}
        </button>

        <p className="text-center text-[10px] font-bold text-slate-500 uppercase tracking-widest">
          {t.formSpam}
        </p>
      </form>
    </div>
  );
};

