      {(['ar', 'en', 'tr'] as LangCode[]).map((l) => (
        <button
          key={l}
          onClick={() => set(l)}
          className={`px-3 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${
