// Fix: Mark children as optional to prevent TypeScript errors in specific build environments where the prop is not correctly inferred from JSX children.
const Modal = ({ isOpen, onClose, children }: { isOpen: boolean; onClose: () => void; children?: React.ReactNode }) => {
  useEffect(() => {
    const handleEsc = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', handleEsc);
    return () => window.removeEventListener('keydown', handleEsc);
  }, [onClose]);

  return (
    <AnimatePresence>
      {isOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <motion.div 
            initial={{ opacity: 0 }} 
            animate={{ opacity: 1 }} 
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="absolute inset-0 bg-slate-900/30 backdrop-blur-sm"
          />
          <motion.div 
            initial={{ opacity: 0, scale: 0.9, y: 30 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.9, y: 30 }}
            className="relative w-full max-w-md bg-white rounded-[40px] shadow-[0_32px_64px_-16px_rgba(0,0,0,0.1)] overflow-hidden"
          >
            <button 
              onClick={onClose}
              className="absolute top-8 right-8 p-2 text-slate-400 hover:text-slate-900 hover:bg-slate-100 rounded-full transition-all z-10"
            >
              <X size={20} />
            </button>
            {children}
          </motion.div>
        </div>
      )}
    </AnimatePresence>
  );
};

const RegistrationForm = ({ onSuccess }: { onSuccess: () => void }) => {
  const [formData, setFormData] = useState({ name: '', email: '' });
  const [status, setStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle');

  const handleSubmit = async (e: React.FormEvent) => {
    // Technical Requirement: preventDefault
    e.preventDefault();

    // Technical Requirement: Read values explicitly & console logs
    const nameValue = formData.name;
    const emailValue = formData.email;

    console.log('--- FORM SUBMISSION START ---');
    console.log('Extracted Name:', nameValue);
    console.log('Extracted Email:', emailValue);

    const payload = {
      name: nameValue,
      email: emailValue
    };

    console.log('JSON Payload:', JSON.stringify(payload));
    setStatus('loading');

    try {
      console.log('Sending fetch request to:', WEBHOOK_URL);
      const response = await fetch(WEBHOOK_URL, {
        method: 'POST', // Technical Requirement: POST only
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });

      console.log('Response Status:', response.status);

      if (!response.ok) {
        throw new Error(`Server responded with status: ${response.status}`);
      }

      setStatus('success');
      console.log('SUCCESS: Data stored in database via webhook');

      // Delay closing to show success message
      setTimeout(() => {
        onSuccess();
        setStatus('idle');
        setFormData({ name: '', email: '' });
      }, 2000);

    } catch (err) {
      console.error('ERROR: Webhook submission failed', err);
      setStatus('error');
      setTimeout(() => setStatus('idle'), 4000);
    } finally {
      console.log('--- FORM SUBMISSION END ---');
    }
  };

  return (
    <div className="p-10">
      <div className="mb-10">
        <div className="w-14 h-14 bg-blue-50 rounded-2xl flex items-center justify-center text-blue-600 mb-6">
          <Globe size={28} />
        </div>
        <h3 className="text-3xl font-bold text-slate-900 mb-3 tracking-tight">Create your account</h3>
        <p className="text-slate-500 font-medium">Start your 14-day free trial. No credit card required.</p>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="space-y-2">
          <label className="text-[11px] font-bold text-slate-400 uppercase tracking-widest px-1">Full Name</label>
          <input 
            required
            type="text"
            placeholder="Jane Smith"
            autoComplete="name"
            value={formData.name}
            onChange={e => setFormData({ ...formData, name: e.target.value })}
            className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-6 py-4 text-slate-900 placeholder:text-slate-300 focus:outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 transition-all text-sm font-medium"
          />
        </div>

        <div className="space-y-2">
          <label className="text-[11px] font-bold text-slate-400 uppercase tracking-widest px-1">Work Email</label>
          <input 
            required
            type="email"
            inputMode="email"
            autoComplete="email"
            placeholder="jane@company.com"
            value={formData.email}
            onChange={e => setFormData({ ...formData, email: e.target.value })}
            className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-6 py-4 text-slate-900 placeholder:text-slate-300 focus:outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 transition-all text-sm font-medium"
          />
        </div>

        <button 
          disabled={status === 'loading' || status === 'success'}
          className={`w-full py-5 rounded-2xl font-bold transition-all flex items-center justify-center gap-3 active:scale-[0.98] shadow-xl ${
            status === 'success' ? 'bg-green-500 text-white shadow-green-500/20' : 
            status === 'error' ? 'bg-red-500 text-white shadow-red-500/20' :
            'bg-blue-600 hover:bg-blue-700 text-white shadow-blue-600/25'
          } disabled:opacity-80`}
        >
          {status === 'loading' ? <RefreshCw className="animate-spin" size={20} /> : null}
          {status === 'success' ? <><CheckCircle2 size={20} /> Success!</> : null}
          {status === 'error' ? <><AlertCircle size={20} /> Error occurred</> : null}
          {status === 'idle' ? 'Create Account' : null}
        </button>

        <p className="text-center text-[10px] font-bold text-slate-400 uppercase tracking-[0.15em] leading-relaxed">
          No spam. Just a useful free solution.
        </p>
      </form>
    </div>
  );
};

