const Modal = ({ isOpen, onClose, children }: { isOpen: boolean; onClose: () => void; children?: React.ReactNode }) => {
  useEffect(() => {
    const handleEsc = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', handleEsc);
    return () => window.removeEventListener('keydown', handleEsc);
  }, [onClose]);

  return (
    <AnimatePresence>
      {isOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <motion.div 
            initial={{ opacity: 0 }} 
            animate={{ opacity: 1 }} 
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm"
          />
          <motion.div 
            initial={{ opacity: 0, scale: 0.95, y: 20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.95, y: 20 }}
            className="relative w-full max-w-md bg-white rounded-[24px] shadow-[0_32px_64px_-16px_rgba(128,0,32,0.15)] overflow-hidden border border-slate-200"
          >
            <div className="absolute top-0 left-0 w-full h-1.5 bg-[#800020]" />
            <button 
              onClick={onClose}
              className="absolute top-6 right-6 p-2 text-slate-400 hover:text-slate-900 hover:bg-slate-100 rounded-lg transition-all z-10"
            >
              <X size={20} />
            </button>
            {children}
          </motion.div>
        </div>
      )}
    </AnimatePresence>
  );
};

const RegistrationForm = ({ onSuccess }: { onSuccess: () => void }) => {
  const [formData, setFormData] = useState({ name: '', email: '' });
  const [status, setStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const payload = { name: formData.name, email: formData.email };

    console.log('--- ATTEMPTING WEBHOOK REGISTRATION ---');
    console.log('Target:', WEBHOOK_URL);
    console.log('Payload:', payload);

    setStatus('loading');

    try {
      const response = await fetch(WEBHOOK_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });

      console.log('Response status:', response.status);

      if (!response.ok) throw new Error(`Server error: ${response.status}`);

      setStatus('success');
      console.log('REGISTRATION SUCCESS');

      setTimeout(() => {
        onSuccess();
        setStatus('idle');
        setFormData({ name: '', email: '' });
      }, 2000);

    } catch (err) {
      console.error('REGISTRATION FAILED', err);
      setStatus('error');
      setTimeout(() => setStatus('idle'), 4000);
    }
  };

  return (
    <div className="p-8">
      <div className="mb-8">
        <div className="w-12 h-12 bg-[#800020]/10 rounded-xl flex items-center justify-center text-[#800020] mb-4">
          <Settings size={24} />
        </div>
        <h3 className="text-2xl font-black text-slate-900 mb-2">Connect Your Account</h3>
        <p className="text-slate-500 text-sm font-medium">Build workflows that run automatically in seconds.</p>
      </div>

      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="space-y-1.5">
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Developer Name</label>
          <input 
            required
            type="text"
            placeholder="e.g. Satoshi Nakamoto"
            value={formData.name}
            onChange={e => setFormData({ ...formData, name: e.target.value })}
            className="w-full bg-slate-50 border border-slate-200 rounded-xl px-5 py-3.5 text-slate-900 placeholder:text-slate-300 focus:outline-none focus:border-[#800020] focus:ring-4 focus:ring-[#800020]/5 transition-all text-sm font-medium"
          />
        </div>

        <div className="space-y-1.5">
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Deployment Email</label>
          <input 
            required
            type="email"
            placeholder="deploy@auraflow.io"
            value={formData.email}
            onChange={e => setFormData({ ...formData, email: e.target.value })}
            className="w-full bg-slate-50 border border-slate-200 rounded-xl px-5 py-3.5 text-slate-900 placeholder:text-slate-300 focus:outline-none focus:border-[#800020] focus:ring-4 focus:ring-[#800020]/5 transition-all text-sm font-medium"
          />
        </div>

        <button 
          disabled={status === 'loading' || status === 'success'}
          className={`w-full py-4 rounded-xl font-black transition-all flex items-center justify-center gap-3 active:scale-[0.98] shadow-lg ${
            status === 'success' ? 'bg-emerald-600 text-white' : 
            status === 'error' ? 'bg-rose-600 text-white' :
            'bg-[#800020] hover:bg-[#600018] text-white shadow-[#800020]/20'
          } disabled:opacity-80 mt-2`}
        >
          {status === 'loading' ? <RefreshCw className="animate-spin" size={18} /> : null}
          {status === 'success' ? <><CheckCircle2 size={18} /> Deployed Successfully</> : null}
          {status === 'error' ? <><AlertCircle size={18} /> Connection Failed</> : null}
          {status === 'idle' ? 'Start Deployment' : null}
        </button>

        <p className="text-center text-[9px] font-black text-slate-400 uppercase tracking-[0.2em] pt-2">
          Technical integration • No spam
        </p>
      </form>
    </div>
  );
};

